Prompt-4.templateFn:
const { text, detailed = false } = params;

// prettier-ignore
return `
  Please analyze the sentiment of the following text:

  "${text}"

  Provide a sentiment analysis that includes:
  - Overall sentiment (positive, negative, neutral, mixed)
  - Confidence score (0-100%)
  - Key emotional indicators
  ${detailed ? '- Detailed emotion breakdown (joy, anger, fear, sadness, surprise, etc.)\n- Specific phrases that indicate each emotion\n- Intensity levels for each emotion detected' : ''}

  Format your response as a clear, structured analysis.
`;

Prompt-user-message-analysis.templateFn:
const { userMessage, additionalContext = '' } = params;

// prettier-ignore
return `
  Analyze the following user message and extract key information:

  User Message: "${userMessage}"

  ${additionalContext ? `Additional Context: ${additionalContext}

` : ''}

  Please provide a detailed analysis including:
  1. Summary: A brief summary of what the user is asking or saying
  2. Intent: The primary intent or goal of the message (e.g., question, request, feedback, etc.)
  3. Entities: Key entities, topics, or concepts mentioned
  4. Category: Categorize the message (e.g., technical_support, general_inquiry, feature_request, etc.)
  5. Urgency: Assess the urgency level (low, medium, high)

  Format your response as a structured analysis.
`;

Action-stream-to-fe.actionFn:
const { text, mode } = params;

const result = await services.llm.streamText({
  model: { provider: 'openai', model: 'gpt-4o' },
  prompt: text,
  system: 'You are a helpful assistant.',
  temperature: 0.7,
  maxTokens: 100,
});

for await (const textPart of result.textStream) {
  services.logger.info('Streaming text to FE', { textPart });

  services.emitter.sendToPlugin('agent', {
    type: 'TOKEN_STREAM',
    token: textPart
  });
}

await result.finishReason

services.emitter.sendToPlugin('agent', {
  type: 'LLM_DONE',
});

Action-md52nfbn25xw7tivi4r1f.actionFn:
const { dbPrompt } = params;

try {
  // Get documents from library service
  const [doc1, doc2] = await Promise.all([
    services.library.getDocByCode('DOC-1'),
    services.library.getDocByCode('DOC-2')
  ]);

  services.logger.info('db example docs', { dbPrompt, doc1, doc2 })

  // Check if documents were found
  if (!doc1) {
    throw new Error('Document DOC-1 not found');
  }
  if (!doc2) {
    throw new Error('Document DOC-2 not found');
  }

  const queryDoc = doc1.content;
  const transactionDoc = doc2.content;

  // Define schema for message classification
  const MessageClassificationSchema = z.object({
    type: z.enum(['query', 'transaction']).describe('Whether the message is a read operation (query) or write operation (transaction)'),
    reasoning: z.string().describe('Brief explanation of why this classification was chosen')
  });

  // Classify the user's message
  const classificationResult = await services.llm.generateObject({
    model: { provider: 'openai', model: 'gpt-4o' },
    schema: MessageClassificationSchema,
    prompt: `Analyze the following message and determine if it's a query (read operation) or transaction (mutation/write operation):

Message: "${dbPrompt}"

A query is any operation that reads or retrieves data without modifying it.
A transaction is any operation that creates, updates, or deletes data.`,
    temperature: 0.3,
  });

  services.logger.info('classificationResult', classificationResult)
  const classification = classificationResult.object;

  // Select appropriate document based on classification
  const selectedDoc = classification.type === 'query' ? queryDoc : transactionDoc;

  services.logger.info('Message classified', {
    type: classification.type,
    reasoning: classification.reasoning
  });

  // Generate the database operation code
  const result = await services.llm.generateText({
    model: { provider: 'openai', model: 'gpt-4o' },
    prompt: dbPrompt,
    system: `
      <examples>
      ${selectedDoc}
      </examples>

      Use the provided examples to write the code to satisfy the user message. Only respond with code (no codeblock backticks).
    `,
    temperature: 0.7,
    maxTokens: 1000,
  });

  // Emit the generated code to database plugin
  services.emitter.sendToPlugin('database', {
    type: 'MAGIC_PROMPT_GENERATED',
    query: result.text
  });

} catch (error) {
  services.logger.error('Error generating database operation', { error });

  // Emit error to database plugin - note: this event type might not exist
  // You may need to handle errors differently based on your system
  services.emitter.sendToPlugin('database', {
    type: 'QUERY_ERROR',
    error: error instanceof Error ? error.message : 'Unknown error occurred'
  });
}

Action-md5phg7q12zc2h1qyscqe.actionFn:
const { searchQuery } = params;

/** 0 ▸ spin up a fresh browser instance */
const browser = services.browser.createBrowser();   // ← NEW: per-call instance

try {
  /* 1 ▸ launch Chromium (headed for demo) */
  await browser.launch({ headless: false });

  /* 2 ▸ navigate to Google */
  await browser.goto('https://www.google.com');

  /* 3 ▸ dismiss cookie/consent banner if it shows up */
  const consentBtn = 'button:has-text("Accept"), button:has-text("Accept all")';
  if (await browser.isVisible(consentBtn)) {
    await browser.click(consentBtn);
  }

  /* 4 ▸ type the query into the (input|textarea)[name=q] and submit */
  const searchField = 'textarea[name="q"], input[name="q"]';
  await browser.waitForSelector(searchField, 5_000);
  await browser.type(searchField, searchQuery);
  await browser.press('Enter');

  /* 5 ▸ wait for the results container */
  await browser.waitForSelector('#search', 10_000);

  services.logger.info('Google search completed', { searchQuery });
} catch (error) {
  services.logger.error('Error during Google search', { error });
} finally {
  /* 6 ▸ always close the instance */
  await browser.close();
}

Action-md5pq4n72eykvz5aiioqi.actionFn:
const { text, mode } = params;

try {
  /** ──────────────────────────────────────────────────────────────
  * 1. Load all procedure-related documents
  * ──────────────────────────────────────────────────────────────*/
  const allDocs = await services.library.getWithinFolder('procedures')

  if (!Array.isArray(allDocs) || allDocs.length === 0) {
    throw new Error('No procedure documents found in “procedures” collection')
  }

  /** 2. Collect the “*.usage” docs and build the LLM prompt */
  const usageDocs = allDocs.filter(d => d.name.endsWith('.usage'))

  services.logger.info('procedure check 1', { allDocs, usageDocs })

  if (usageDocs.length === 0) {
    throw new Error('No “*.usage” documents found')
  }

  const procedureNames = usageDocs.map(d => d.name.replace(/\.usage$/, ''))
  const proceduresPrompt = usageDocs
    .map(d => {
      const name = d.name.replace(/\.usage$/, '')
      return `<procedure>Name: ${name} Usage: ${d.content}</procedure>`
    })
    .join('\n\n')

  /** 3. Ask the LLM which procedure (if any) matches the user’s request */
  const ProcedureSelectionSchema = z.object({
    procedure: z.enum([...procedureNames, 'none']).describe('Chosen procedure name or "none"')
  })

  const llmResult = await services.llm.generateObject({
    model: { provider: 'openai', model: 'gpt-4o' },
    schema: ProcedureSelectionSchema,
    prompt: `
    You are an expert router. Given a user message, decide which procedure (if any) best handles it.

    <procedures>
    ${proceduresPrompt}
    </procedures>

    Respond with JSON matching the schema, using one of the procedure names above or "none".

    User message: """${text}"""
  `,
    temperature: 0
  })



  const { procedure } = llmResult.object

  services.logger.info('procedure check 2', { proceduresPrompt, procedure })


  /** ──────────────────────────────────────────────────────────────
   * 4. Route to the chosen procedure or fall back to streaming
   * ──────────────────────────────────────────────────────────────*/
  if (procedure !== 'none') {
    const procDoc = allDocs.find(d => d.name === `${procedure}.procedure`)
    if (!procDoc) {
      throw new Error(`Procedure implementation document “${procedure}.procedure” not found`)
    }

    const actionKey = procDoc.content.trim()

    await services.action.getAndExecute(actionKey, { searchQuery: text })
  } else {
    await services.action.getAndExecute('Stream to FE', { text })
  }
} catch (error) {
  services.logger.error('Procedure routing failed', { error });
  // Fallback behaviour here if needed
}

